@props([ 'name' => null, 'id' => null, 'type' => 'text', 'label' => null, 'value' => null, 'placeholder' => null, 'help' => null, 'error' => null, 'required' => false, 'disabled' => false, 'icon' => null, 'iconRight' => null, ]) @php $inputId = $id ?: ($name ?: 'ui-input-' . uniqid()); $hasError = $error || ($name && isset($errors) && $errors->has($name)); $errorMessage = $error ?: ($name && isset($errors) ? $errors->first($name) : null); $inputValue = $value !== null ? $value : ($name ? old($name) : ''); $inputClasses = [ 'ui-input', $icon ? 'ui-input-has-left-icon' : '', $iconRight ? 'ui-input-has-right-icon' : '', $hasError ? 'is-invalid' : '', ]; $inputClasses = trim(implode(' ', array_filter($inputClasses))); @endphp <div class="ui-form-group"> @if($label) <label for="{{ $inputId }}" class="ui-label">{{ $label }} @if($required) <span class="ui-label-required">*</span> @endif </label> @endif <div class="ui-input-wrapper"> @if($icon) <span class="ui-input-icon-left"><i class="{{ $icon }}"></i></span> @endif <input type="{{ $type }}" id="{{ $inputId }}" @if($name) name="{{ $name }}" @endif value="{{ $inputValue }}" @if($placeholder) placeholder="{{ $placeholder }}" @endif @if($required) required @endif @if($disabled) disabled @endif {{ $attributes->merge(['class' => $inputClasses]) }} /> @if($iconRight) <span class="ui-input-icon-right"><i class="{{ $iconRight }}"></i></span> @endif </div> @if($hasError) <span class="ui-error-text">{{ $errorMessage }}</span> @elseif($help) <span class="ui-help-text">{{ $help }}</span> @endif </div>